/* ------------------------------------------------------------------ */
/* rights_grants                                                       */
/* ------------------------------------------------------------------ */

export const rightsGrants = pgTable(
  "rights_grants",
  {
    id: id(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => articles.id, { onDelete: "cascade" }),
    grantorId: uuid("grantor_id")
      .notNull()
      .references(() => users.id, { onDelete: "restrict" }),

    /** The contract version whose article 4 fixes this licence's scope (§7.1). */
    agreementVersionId: uuid("agreement_version_id").references(() => agreementVersions.id, {
      onDelete: "restrict",
    }),
    bylineChoice: bylineChoiceEnum("byline_choice"),

    grantType: grantTypeEnum("grant_type").notNull(),

    // FSEK requires each economic right to be listed one by one (art. 52)
    rightAdaptation: boolean("right_adaptation").notNull().default(false), // m.21 işleme
    rightReproduction: boolean("right_reproduction").notNull().default(false), // m.22 çoğaltma
    rightDistribution: boolean("right_distribution").notNull().default(false), // m.23 yayma
    rightCommunicationToPublic: boolean("right_communication_to_public").notNull().default(false), // m.25 umuma iletim

    channels: text("channels")
      .array()
      .notNull()
      .default(sql`'{}'::text[]`),
    exclusivityMonths: integer("exclusivity_months"),
    territory: text("territory").notNull().default("worldwide"),
    consideration: considerationEnum("consideration").notNull().default("none"),
    commercialUseIncluded: boolean("commercial_use_included").notNull().default(false),

    /** sha256 of the work's body as it stood when the licence was declared. */
    formTextHash: text("form_text_hash").notNull(),
    /**
     * The body itself, kept beside its hash (D-238). The hash proves nothing
     * changed; this is what was actually licensed, so it has to be readable
     * years later without reconstructing it from the version history.
     */
    acceptedBodyMarkdown: text("accepted_body_markdown"),
    /** Which `article_versions` number the declaration was made against. */
    acceptedVersion: integer("accepted_version"),
    formPdfMediaId: uuid("form_pdf_media_id").references(() => media.id, { onDelete: "set null" }),

    status: grantStatusEnum("status").notNull().default("pending"),
    signedAt: timestamp("signed_at", { withTimezone: true }),
    signedIp: text("signed_ip"),
    signedUserAgent: text("signed_user_agent"),
    declinedAt: timestamp("declined_at", { withTimezone: true }),
    declinedReason: text("declined_reason"),
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    revokedBy: uuid("revoked_by").references(() => users.id, { onDelete: "set null" }),
    /** Set when the writer was last nudged, so reminders do not repeat daily. */
    reminderSentAt: timestamp("reminder_sent_at", { withTimezone: true }),

    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    // One live approval per article; revoked and declined ones stay as history
    uniqueIndex("rights_grants_article_active_unique")
      .on(t.articleId)
      .where(sql`${t.status} in ('pending', 'signed')`),
    index("rights_grants_grantor_idx").on(t.grantorId),
    index("rights_grants_status_idx").on(t.status),
  ],
);

