/**
 * The moderation blacklist (module 4). Words are stored normalized (lowercase,
 * Turkish locale) and matched case-insensitively as substrings, so suffixed
 * forms are covered too. Removal is a soft delete so an admin can restore.
 */
export const bannedWords = pgTable(
  "banned_words",
  {
    id: id(),
    word: text("word").notNull(),
    createdBy: uuid("created_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
  },
  (t) => [
    // A live word is unique; soft-deleted ones stay as history
    uniqueIndex("banned_words_word_unique").on(t.word).where(sql`${t.deletedAt} is null`),
  ],
);

/** A reader's comment on a published magazine article. */
export const communityComments = pgTable(
  "community_comments",
  {
    id: id(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => articles.id, { onDelete: "cascade" }),
    authorId: uuid("author_id").references(() => users.id, { onDelete: "set null" }),
    /** The comment with banned words already masked (module 4). */
    body: text("body").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
  },
  (t) => [
    index("community_comments_article_idx").on(t.articleId, t.createdAt),
  ],
);

/** A message in the community chat; an optional quote references another one. */
export const communityMessages = pgTable(
  "community_messages",
  {
    id: id(),
    authorId: uuid("author_id").references(() => users.id, { onDelete: "set null" }),
    body: text("body").notNull(),
    // Self reference: the explicit return type breaks the circular inference
    quotedMessageId: uuid("quoted_message_id").references(
      (): AnyPgColumn => communityMessages.id,
      { onDelete: "set null" },
    ),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
  },
  (t) => [index("community_messages_created_idx").on(t.createdAt)],
);

/**
 * The 5651 m. 5 traffic record of every piece of user content (D-088).
 *
 * Kept apart from `audit_log` on purpose: the audit trail lives for ten years
 * and a trigger forbids deleting from it, while a traffic record has a
 * statutory one-year life and is pruned once that year is over.
 */
export const trafficLogs = pgTable(
  "traffic_logs",
  {
    id: id(),
    // The record must outlive an anonymised account, so the link only loosens
    userId: uuid("user_id").references(() => users.id, { onDelete: "set null" }),
    action: text("action").notNull(),
    entityType: text("entity_type").notNull(),
    entityId: uuid("entity_id"),
    ip: text("ip"),
    userAgent: text("user_agent"),
    createdAt: createdAt(),
  },
  (t) => [
    index("traffic_logs_created_idx").on(t.createdAt),
    index("traffic_logs_entity_idx").on(t.entityType, t.entityId),
  ],
);

/* ------------------------------------------------------------------ */
/* social graph (D-089)                                                */
/* ------------------------------------------------------------------ */

/*
 * Follows, blocks and bookmarks break the soft-delete convention on purpose:
 * they carry no content, and keeping a retracted follow or a lifted block
 * would store a piece of someone's social graph they took back (KVKK data
 * minimisation). Undoing one deletes the row.
 */

export const follows = pgTable(
  "follows",
  {
    id: id(),
    followerId: uuid("follower_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    followeeId: uuid("followee_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("follows_pair_unique").on(t.followerId, t.followeeId),
    index("follows_followee_idx").on(t.followeeId),
  ],
);

/** A block works both ways: neither side can follow, message or reach the other. */
export const userBlocks = pgTable(
  "user_blocks",
  {
    id: id(),
    blockerId: uuid("blocker_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    blockedId: uuid("blocked_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("user_blocks_pair_unique").on(t.blockerId, t.blockedId),
    index("user_blocks_blocked_idx").on(t.blockedId),
  ],
);

