/** Membership is a toggle and follows the hard-delete rule of D-089. */
export const communityMemberships = pgTable(
  "community_memberships",
  {
    id: id(),
    communityId: uuid("community_id")
      .notNull()
      .references(() => communities.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("community_memberships_pair_unique").on(t.communityId, t.userId),
    index("community_memberships_user_idx").on(t.userId),
  ],
);

/* ------------------------------------------------------------------ */
/* member posts (D-090)                                                */
/* ------------------------------------------------------------------ */

/** A member's short post; a reply points at the post it answers. */
export const posts = pgTable(
  "posts",
  {
    id: id(),
    authorId: uuid("author_id").references(() => users.id, { onDelete: "set null" }),
    /** Stored with banned words already masked (D-040). */
    body: text("body").notNull(),
    replyToId: uuid("reply_to_id").references((): AnyPgColumn => posts.id, {
      onDelete: "set null",
    }),
    /** The community the post was shared in (D-093); null for a plain post. */
    communityId: uuid("community_id").references(() => communities.id, { onDelete: "set null" }),
    /** The moderator who took it down; null when the author deleted it. */
    removedBy: uuid("removed_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
  },
  (t) => [
    index("posts_author_idx").on(t.authorId, t.createdAt),
    index("posts_reply_to_idx").on(t.replyToId, t.createdAt),
    index("posts_created_idx").on(t.createdAt),
    index("posts_community_idx").on(t.communityId, t.createdAt),
  ],
);

/** Likes and reposts are toggles and follow the hard-delete rule of D-089. */
export const postLikes = pgTable(
  "post_likes",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    postId: uuid("post_id")
      .notNull()
      .references(() => posts.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("post_likes_pair_unique").on(t.userId, t.postId),
    index("post_likes_post_idx").on(t.postId),
  ],
);

export const postReposts = pgTable(
  "post_reposts",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    postId: uuid("post_id")
      .notNull()
      .references(() => posts.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("post_reposts_pair_unique").on(t.userId, t.postId),
    index("post_reposts_post_idx").on(t.postId),
  ],
);

/** A reader's private reading list: an article or a post, never both. */
export const bookmarks = pgTable(
  "bookmarks",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    articleId: uuid("article_id").references(() => articles.id, { onDelete: "cascade" }),
    postId: uuid("post_id").references(() => posts.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [
    uniqueIndex("bookmarks_user_article_unique").on(t.userId, t.articleId),
    uniqueIndex("bookmarks_user_post_unique").on(t.userId, t.postId),
    check("bookmarks_one_target", sql`num_nonnulls(${t.articleId}, ${t.postId}) = 1`),
  ],
);

/* ------------------------------------------------------------------ */
/* content reports (D-090)                                             */
/* ------------------------------------------------------------------ */

/** Every kind of user content a member can report, including later modules. */
export const reportTargetEnum = pgEnum("report_target", [
  "post",
  "comment",
  "direct_message",
  "anon_message",
  "member",
]);

export const reportCategoryEnum = pgEnum("report_category", [
  "harassment",
  "hate",
  "personal_data",
  "copyright",
  "spam",
  "illegal",
  "impersonation",
  "other",
]);

export const reportStatusEnum = pgEnum("report_status", ["open", "removed", "dismissed"]);

/**
 * A member's report about a piece of content (5651 m. 9 notice path). The
 * snapshot keeps the text as it was reported, so the moderator judges what the
 * reporter saw even if the author deletes or the content is private.
 */
export const contentReports = pgTable(
  "content_reports",
  {
    id: id(),
    reporterId: uuid("reporter_id").references(() => users.id, { onDelete: "set null" }),
    targetType: reportTargetEnum("target_type").notNull(),
    targetId: uuid("target_id").notNull(),
    targetUserId: uuid("target_user_id").references(() => users.id, { onDelete: "set null" }),
    category: reportCategoryEnum("category").notNull(),
    reason: text("reason"),
    snapshot: text("snapshot").notNull(),
    status: reportStatusEnum("status").notNull().default("open"),
    resolvedBy: uuid("resolved_by").references(() => users.id, { onDelete: "set null" }),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
    resolutionNote: text("resolution_note"),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index("content_reports_status_idx").on(t.status, t.createdAt),
    index("content_reports_target_idx").on(t.targetType, t.targetId),
  ],
);

/* ------------------------------------------------------------------ */
/* private messages (D-091)                                            */
/* ------------------------------------------------------------------ */

/**
 * A private conversation between exactly two members. The pair is stored in
 * order (`member_a_id` < `member_b_id`), so it has one row whoever wrote first.
 */
export const conversations = pgTable(
  "conversations",
  {
    id: id(),
    memberAId: uuid("member_a_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    memberBId: uuid("member_b_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    lastMessageAt: timestamp("last_message_at", { withTimezone: true }).notNull().defaultNow(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex("conversations_pair_unique").on(t.memberAId, t.memberBId),
    index("conversations_member_b_idx").on(t.memberBId),
    check("conversations_ordered_pair", sql`${t.memberAId} < ${t.memberBId}`),
  ],
);

/** Each member's own view of a conversation: what they read and what they cleared. */
export const conversationStates = pgTable(
  "conversation_states",
  {
    id: id(),
    conversationId: uuid("conversation_id")
      .notNull()
      .references(() => conversations.id, { onDelete: "cascade" }),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    lastReadAt: timestamp("last_read_at", { withTimezone: true }),
    /** "Delete conversation" hides everything before this moment, for this member only. */
    clearedAt: timestamp("cleared_at", { withTimezone: true }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("conversation_states_pair_unique").on(t.conversationId, t.userId)],
);

export const directMessages = pgTable(
  "direct_messages",
  {
    id: id(),
    conversationId: uuid("conversation_id")
      .notNull()
      .references(() => conversations.id, { onDelete: "cascade" }),
    senderId: uuid("sender_id").references(() => users.id, { onDelete: "set null" }),
    /** Stored with banned words already masked (D-040). */
    body: text("body").notNull(),
    /** The moderator who removed it after a report; null when gone with the account. */
    removedBy: uuid("removed_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
  },
  (t) => [index("direct_messages_conversation_idx").on(t.conversationId, t.createdAt)],
);

/* ------------------------------------------------------------------ */
/* anonymous box (D-092, D-185)                                        */
/* ------------------------------------------------------------------ */

/**
 * A message left without the sender's name. Since D-185 the box is the
 * magazine's: a message with no recipient goes to the admins, for the
 * "Eğlence & Dedikodu" section. Rows with a recipient are left from the member
 * boxes of D-092, which closed. Anonymous to the reader only: the sender is
 * stored, because the magazine must be able to answer for it (5651 m. 5).
 */
export const anonMessages = pgTable(
  "anon_messages",
  {
    id: id(),
    /** Null for the magazine's box (D-185); a member for the old member boxes. */
    recipientId: uuid("recipient_id").references(() => users.id, { onDelete: "cascade" }),
    senderId: uuid("sender_id").references(() => users.id, { onDelete: "set null" }),
    /** Stored with banned words already masked (D-040). */
    body: text("body").notNull(),
    readAt: timestamp("read_at", { withTimezone: true }),
    /** The recipient deleted it from their box. */
    hiddenAt: timestamp("hidden_at", { withTimezone: true }),
    removedBy: uuid("removed_by").references(() => users.id, { onDelete: "set null" }),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    deletedAt: deletedAt(),
  },
  (t) => [
    index("anon_messages_recipient_idx").on(t.recipientId, t.createdAt),
    index("anon_messages_sender_idx").on(t.senderId, t.createdAt),
  ],
);

/**
 * A sender the recipient silenced without learning who it is. Not a block: a
 * block shows on the blocked person's profile and would give the name away.
 */
export const anonMutes = pgTable(
  "anon_mutes",
  {
    id: id(),
    recipientId: uuid("recipient_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    senderId: uuid("sender_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex("anon_mutes_pair_unique").on(t.recipientId, t.senderId)],
);

/* ------------------------------------------------------------------ */
/* team_avatars (D-194)                                                */
/* ------------------------------------------------------------------ */

/**
 * A team member's illustrated avatar: the chosen parts and the PNG drawn from
 * them. One per account; saving again replaces it.
 *
 * Deleted for real, not soft deleted: the avatar is the member's own optional
 * creation, nothing refers to it, and "Avatarımı sil" should leave nothing
 * behind (KVKK). The audit log keeps that it existed.
 */
export const teamAvatars = pgTable(
  "team_avatars",
  {
    id: id(),
    userId: uuid("user_id")
      .notNull()
      .references(() => users.id, { onDelete: "cascade" }),
    /** As the member wants it credited on the team page; not the account name. */
    displayName: text("display_name").notNull(),
    teamRole: text("team_role").notNull(),
    /** Only catalogue ids (`src/lib/avatar/registry.ts`), so the builder can reopen it. */
    config: jsonb("config").notNull(),
    configVersion: integer("config_version").notNull(),
    /** The transparent PNG in object storage; regenerated from `config` if it goes missing. */
    pngStorageKey: text("png_storage_key"),

    /* The team form (D-226). Null until the member fills it in; it is asked
       for separately from the avatar and is not required to keep one. */

    /** A line of their own for the team page, at most 55 characters. */
    motto: text("motto"),
    /**
     * How they want to be named on the team page. This is NOT the article
     * byline: that one is signed per work on `rights_grants.byline_choice`
     * (FSEK), and neither may be read for the other.
     */
    teamByline: bylineChoiceEnum("team_byline"),
    zodiac: zodiacEnum("zodiac"),
    /** When the form was last answered; null means it never was. */
    teamFormAt: timestamp("team_form_at", { withTimezone: true }),

    /**
     * The admin's own tick: they have made this member's post (D-232). It is a
     * time rather than a flag so that a later `updated_at` tells us the member
     * changed the avatar after the tick, and the card can come back up marked
     * as changed. Nobody but the admin sees or sets it.
     */
    processedAt: timestamp("processed_at", { withTimezone: true }),

    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [uniqueIndex("team_avatars_user_unique").on(t.userId)],
);

/* ------------------------------------------------------------------ */
/* audit_log (append only, D-015)                                      */
/* ------------------------------------------------------------------ */

export const auditLog = pgTable(
  "audit_log",
  {
    id: id(),
    /** Null for actions performed by scheduled jobs rather than a person. */
    actorId: uuid("actor_id").references(() => users.id, { onDelete: "set null" }),
    action: text("action").notNull(),
    entityType: text("entity_type").notNull(),
    entityId: uuid("entity_id"),
    before: jsonb("before"),
    after: jsonb("after"),
    ip: text("ip"),
    createdAt: createdAt(),
  },
  (t) => [
    index("audit_log_entity_idx").on(t.entityType, t.entityId),
    index("audit_log_created_at_idx").on(t.createdAt),
    index("audit_log_actor_idx").on(t.actorId),
  ],
);

